    /// THE MARK UNDER THE POINTER IS FOUND BY THE SAME ARITHMETIC THAT DREW
    /// IT.
    ///
    /// The canvas paints the marks and cannot hit-test them, so the click
    /// asks `flow_hull_at`: the hull's ground projected at the live camera and
    /// placed by the cover transform. A mark nobody can click is a mark that
    /// cannot be selected, and a selection that lands one header off (the pin
    /// bug this replaces) is the same failure wearing a different hat.
    #[gpui::test]
    fn a_click_finds_the_hull_its_mark_was_drawn_at(cx: &mut gpui::TestAppContext) {
        let (tx, _rx) = std::sync::mpsc::channel();
        let (view, cx) = cx.add_window_view(|_, _| {
            let mut demo = IslandDemo::new(fixture_roster(), 0, 0, SessionView::default(), tx);
            demo.flow_draft = crate::fixtures::reopened_twelve();
            demo.map_dims = (960.0, 1048.0);
            demo.map_window = (1920.0, 1080.0);
            demo.map_center = (-6.1080, 106.9100);
            demo.map_zoom = 11.0;
            demo
        });
        cx.update(|_, app| {
            view.update(app, |demo, cx| {
                let draft = demo.flow_draft.clone().expect("a draft");
                let hull = draft
                    .force
                    .hulls()
                    .find(|h| h.start.is_some())
                    .cloned()
                    .expect("a placed hull");
                let _ = cx;
                let start = hull.start.expect("it has ground");
                let (mx, my) = map_geometry::project_mercator(
                    start.lat,
                    start.lon,
                    demo.map_center,
                    demo.map_zoom,
                    960.0,
                    1048.0,
                );
                let (s, ox, oy) = map_view(960.0, 1048.0, 1920.0, 1080.0);
                let at = (
                    ox as f32 + (mx as f32) * s as f32,
                    oy as f32 + (my as f32) * s as f32,
                );
                assert_eq!(
                    demo.flow_hull_at(at),
                    Some(hull.unit_id),
                    "the mark under the pointer is the hull that was drawn there"
                );
                assert_eq!(
                    demo.flow_hull_at((0.0, 0.0)),
                    None,
                    "and the corner of the window is nobody`s"
                );
            });
        });
    }

    /// A DROP ON THE EMPTY CANVAS MAKES THE GROUP THE SHEET PROMISES.
    ///
    /// The canvas said `DROP ON EMPTY CANVAS → A NEW GROUP · PICK ITS
    /// ECHELON` and had no drop handler at all, so every such drop came back
    /// as "released on nothing". The echelon is the one chosen on the left,
    /// and the cards land in the new group as its units.
    #[gpui::test]
    fn a_drop_on_the_canvas_makes_a_group_at_the_chosen_echelon(cx: &mut gpui::TestAppContext) {
        let (tx, _rx) = std::sync::mpsc::channel();
        let (view, cx) = cx.add_window_view(|_, _| {
            let mut demo = IslandDemo::new(fixture_roster(), 0, 0, SessionView::default(), tx);
            demo.flow_draft = crate::fixtures::reopened_twelve();
            demo.flow_stage = crate::draft::Stage::Groups;
            demo.flow_echelon = crate::groups::GroupKind::SatuanTugas;
            demo
        });
        cx.update(|_, app| {
            view.update(app, |demo, cx| {
                let before = demo
                    .flow_draft
                    .as_ref()
                    .expect("a draft")
                    .groups
                    .staged_groups()
                    .count();
                demo.flow_carry = Some(FlowCarry {
                    unit_ids: vec![590, 591],
                    group_id: None,
                    label: "KRI Makassar".to_string(),
                    from: (10.0, 10.0),
                    at: (200.0, 200.0),
                    lifted: true,
                });
                assert!(demo.carry_into_new_group(cx), "the canvas takes the drop");
                let draft = demo.flow_draft.clone().expect("a draft");
                let groups: Vec<_> = draft.groups.staged_groups().cloned().collect();
                assert_eq!(groups.len(), before + 1, "one group more");
                let made = groups.last().expect("the new group");
                // A HULL IS AN UNSUR: the canvas makes the level that holds
                // hulls, which is a Satuan Tugas, never a Gugus.
                assert_eq!(made.kind, crate::groups::GroupKind::SatuanTugas);
                assert_eq!(made.units, vec![590, 591], "the cards are its units");
                assert_eq!(demo.flow_group, Some(made.local_id), "and it is chosen");
                assert!(demo.flow_carry.is_none(), "the cards left the hand");
            });
        });
    }

    /// A DROP ON A GROUP'S ROW JOINS THAT GROUP, AND ONE HULL STAYS ONE PLACE.
    ///
    /// The union is taken rather than the append — a hull already in the group
    /// is not listed twice — and a hull another group already holds is refused
    /// with the refusal on the bottom line, which is the server's rule said
    /// locally and said now.
    #[gpui::test]
    fn a_drop_on_a_group_row_joins_it_and_refuses_a_double_place(cx: &mut gpui::TestAppContext) {
        let (tx, _rx) = std::sync::mpsc::channel();
        let (view, cx) = cx.add_window_view(|_, _| {
            let mut demo = IslandDemo::new(fixture_roster(), 0, 0, SessionView::default(), tx);
            demo.flow_draft = crate::fixtures::groups_draft();
            demo.flow_stage = crate::draft::Stage::Groups;
            demo
        });
        cx.update(|_, app| {
            view.update(app, |demo, cx| {
                let groups: Vec<_> = demo
                    .flow_draft
                    .as_ref()
                    .expect("a draft")
                    .groups
                    .staged_groups()
                    .cloned()
                    .collect();
                let target = groups.first().expect("a group");
                let already = target.units[0];
                let free = demo
                    .flow_draft
                    .as_ref()
                    .expect("a draft")
                    .force
                    .hulls()
                    .map(|h| h.unit_id)
                    .find(|id| !groups.iter().any(|g| g.units.contains(id)))
                    .expect("a loose hull");
                demo.flow_carry = Some(FlowCarry {
                    unit_ids: vec![already, free],
                    group_id: None,
                    label: "two cards".to_string(),
                    from: (0.0, 0.0),
                    at: (0.0, 0.0),
                    lifted: true,
                });
                assert!(demo.carry_into_group(target.local_id, cx));
                let after = demo
                    .flow_draft
                    .clone()
                    .expect("a draft")
                    .groups
                    .get(target.local_id)
                    .cloned()
                    .expect("the group");
                assert_eq!(
                    after.units.iter().filter(|id| **id == already).count(),
                    1,
                    "a hull already in the group is not listed twice"
                );
                assert!(after.units.contains(&free), "and the free hull joined");
                assert_eq!(
                    after.units.len(),
                    target.units.len() + 1,
                    "exactly one card was added"
                );
            });
        });
    }

    /// THE BASKET IS THE TREE (`§7.2`): every body is a channel, a body is
    /// indented under the body above it, its cards sit under it, and the hulls
    /// no body holds are last, under `UNGROUPED`.
    ///
    /// The defect this pins: cards were one flat grid with the group rows
    /// stacked above it, so a card's channel was a caption rather than a place.
    #[test]
    fn basket_channels_follow_the_organisation() {
        let draft = crate::fixtures::groups_draft().expect("the groups fixture");
        let channels = basket_channels(&draft);
        let shape: Vec<(String, usize, usize)> = channels
            .iter()
            .map(|channel| (channel.label.clone(), channel.depth, channel.cards.len()))
            .collect();
        assert_eq!(
            shape,
            vec![
                ("OPGAB JAYA".to_string(), 0, 0),
                ("GUS-1".to_string(), 1, 0),
                ("TG-1".to_string(), 2, 3),
                ("TG-2".to_string(), 2, 2),
                ("UNGROUPED".to_string(), 0, 4),
            ],
            "the tree, its cards, and the loose hulls"
        );
        // Every hull appears exactly once, under exactly one channel.
        let total: usize = channels.iter().map(|channel| channel.cards.len()).sum();
        assert_eq!(total, draft.unit_count(), "no card is lost or doubled");
        assert_eq!(channels.last().and_then(|c| c.group_id), None, "loose last");
    }

    /// A GROUP DROPPED ON A GROUP'S BAND RE-PARENTS UNDER IT (`§6.2`).
    ///
    /// The gesture is the same one the basket's cards use, but the thing in the
    /// hand is the body itself: `set_parent`, not `set_units`.
    #[gpui::test]
    fn a_group_dropped_on_a_band_nests_under_it(cx: &mut gpui::TestAppContext) {
        let (tx, _rx) = std::sync::mpsc::channel();
        let (view, cx) = cx.add_window_view(|_, _| {
            let mut demo = IslandDemo::new(fixture_roster(), 0, 0, SessionView::default(), tx);
            demo.flow_draft = crate::fixtures::groups_draft();
            demo.flow_stage = crate::draft::Stage::Groups;
            demo
        });
        cx.update(|_, app| {
            view.update(app, |demo, cx| {
                let draft = demo.flow_draft.clone().expect("a draft");
                let id_of = |name: &str| {
                    draft
                        .groups
                        .staged_groups()
                        .find(|g| g.name == name)
                        .map(|g| g.local_id)
                        .expect("a group")
                };
                let (opgab, gus) = (id_of("OPGAB JAYA"), id_of("GUS-1"));
                // Take the Gugus out from under the operation, so the drop is
                // the thing that puts it back.
                demo.flow_draft
                    .as_mut()
                    .expect("a draft")
                    .groups
                    .set_parent(gus, None)
                    .expect("a root");
                demo.flow_carry = Some(FlowCarry {
                    unit_ids: Vec::new(),
                    group_id: Some(gus),
                    label: "GUS-1".to_string(),
                    from: (0.0, 0.0),
                    at: (40.0, 40.0),
                    lifted: true,
                });
                assert!(demo.carry_into_group(opgab, cx), "the band takes the body");
                let after = demo.flow_draft.clone().expect("a draft");
                assert_eq!(
                    after.groups.get(gus).map(|g| g.parent),
                    Some(Some(opgab)),
                    "the Gugus is under the operation again"
                );
                assert_eq!(demo.flow_group, Some(opgab), "and the parent is chosen");
                assert!(demo.flow_carry.is_none(), "the body left the hand");
            });
        });
    }

    /// A GROUP DROPPED ON A RUNG GOES UNDER THAT LEVEL (`§6.2`).
    ///
    /// The canvas needs the upper level already drawn; the rung names the LEVEL,
    /// so the gesture works when the upper body is elsewhere — and when the tree
    /// has none yet, the rung makes one rather than refusing the drop.
    #[gpui::test]
    fn a_group_dropped_on_a_rung_uses_or_makes_a_body_at_that_level(cx: &mut gpui::TestAppContext) {
        let (tx, _rx) = std::sync::mpsc::channel();
        let (view, cx) = cx.add_window_view(|_, _| {
            let mut demo = IslandDemo::new(fixture_roster(), 0, 0, SessionView::default(), tx);
            demo.flow_draft = crate::fixtures::groups_draft();
            demo.flow_stage = crate::draft::Stage::Groups;
            demo
        });
        cx.update(|_, app| {
            view.update(app, |demo, cx| {
                let draft = demo.flow_draft.clone().expect("a draft");
                let id_of = |name: &str| {
                    draft
                        .groups
                        .staged_groups()
                        .find(|g| g.name == name)
                        .map(|g| g.local_id)
                        .expect("a group")
                };
                let (gus, tg2) = (id_of("GUS-1"), id_of("TG-2"));
                demo.flow_draft
                    .as_mut()
                    .expect("a draft")
                    .groups
                    .set_parent(tg2, None)
                    .expect("a root");
                demo.flow_group = None;
                demo.flow_carry = Some(FlowCarry {
                    unit_ids: Vec::new(),
                    group_id: Some(tg2),
                    label: "TG-2".to_string(),
                    from: (0.0, 0.0),
                    at: (40.0, 40.0),
                    lifted: true,
                });
                assert!(demo.carry_into_echelon(crate::groups::GroupKind::Gugus, cx));
                let after = demo.flow_draft.clone().expect("a draft");
                assert_eq!(
                    after.groups.get(tg2).map(|g| g.parent),
                    Some(Some(gus)),
                    "the existing Gugus took it"
                );

                // And with no Gugus in the tree, the rung makes one.
                demo.flow_draft = crate::fixtures::reopened_twelve();
                let sat = demo
                    .flow_draft
                    .as_mut()
                    .expect("a draft")
                    .groups
                    .stage_group(
                        0,
                        "TG-A",
                        crate::groups::GroupKind::SatuanTugas,
                        None,
                        None,
                        vec![],
                    )
                    .expect("a satgas");
                demo.flow_group = None;
                demo.flow_carry = Some(FlowCarry {
                    unit_ids: Vec::new(),
                    group_id: Some(sat),
                    label: "TG-A".to_string(),
                    from: (0.0, 0.0),
                    at: (40.0, 40.0),
                    lifted: true,
                });
                assert!(demo.carry_into_echelon(crate::groups::GroupKind::Gugus, cx));
                let after = demo.flow_draft.clone().expect("a draft");
                let parent = after
                    .groups
                    .get(sat)
                    .and_then(|g| g.parent)
                    .expect("a parent");
                assert_eq!(
                    after.groups.get(parent).map(|g| g.kind),
                    Some(crate::groups::GroupKind::Gugus),
                    "the rung made the level it named"
                );
            });
        });
    }

