    /// A HULL'S COMMANDER IS ON ITS CARD, AND A GROUP'S ON ITS CHANNEL
    /// (`§8.3`): the basket says who commands what before the operator drops
    /// another person on it.
    #[test]
    fn basket_cards_and_channels_read_their_commander() {
        let draft = crate::fixtures::groups_draft().expect("the groups fixture");
        let channels = basket_channels(&draft);
        let tg1 = channels
            .iter()
            .find(|channel| channel.label == "TG-1")
            .expect("the satgas channel");
        assert_eq!(tg1.commander, Some(4), "the group's own commander");
        let first = &tg1.cards[0];
        assert_eq!(first.unit_id, 351);
        assert_eq!(first.commander, Some(2), "the hull's commander");
        let ungrouped = channels.last().expect("the loose channel");
        assert_eq!(ungrouped.label, "UNGROUPED");
        assert!(ungrouped.commander.is_none(), "nobody commands a bucket");
    }

