    /// THE PRESS SENDS THE WHOLE DRAFT, and the answer REPLACES it: the
    /// journal is the draft's own memory of what it wrote, so a second press
    /// reads it instead of a copy (§9.3).
    #[gpui::test]
    fn a_press_sends_the_draft_and_the_answer_replaces_it(cx: &mut gpui::TestAppContext) {
        let (tx, rx) = std::sync::mpsc::channel();
        let (view, cx) = cx.add_window_view(|_, _| {
            let mut demo = IslandDemo::new(fixture_roster(), 0, 0, SessionView::default(), tx);
            demo.flow_draft = crate::fixtures::review_draft();
            demo
        });
        let original = cx.update(|_window, app| {
            view.update(app, |demo, cx| {
                demo.press(crate::draft::Verb::SaveAsGameSession, cx);
                assert!(demo.press_busy, "the answer is waited for");
                demo.flow_draft.clone().expect("a draft")
            })
        });
        match rx.try_recv().expect("the press reached the sink") {
            ToBinary::Press { verb, draft } => {
                assert_eq!(verb, crate::draft::Verb::SaveAsGameSession);
                assert_eq!(draft.terms.name, "Baltic Shield 26");
                assert_eq!(draft.unit_count(), 9, "the force crosses with it");
            }
            other => panic!("expected a press, got {other:?}"),
        }

        // The answer: a stop at 02, with the draft's journal grown.
        let mut answered = original;
        // `adopt_game` is the one call that sets the id AND journals 01 —
        // the same pair the press's own `record` does when the create answers
        // with the game it made.
        answered.journal.adopt_game(42);
        answered
            .journal
            .note_failed(crate::draft::Ladder::Game, 2, 502, Some("req-1".into()));
        cx.update(|_window, app| {
            view.update(app, |demo, cx| {
                demo.apply_press(
                    PressAnswer {
                        draft: answered.clone(),
                        verb: crate::draft::Verb::SaveAsGameSession,
                        outcome: crate::commit::Outcome::Stopped {
                            position: 2,
                            name: "SEATS",
                            failure: crate::commit::Failure {
                                status: Some(502),
                                request_id: Some("req-1".into()),
                                sentence: "THE SERVER DID NOT ANSWER".into(),
                            },
                            resume_at: 2,
                        },
                    },
                    cx,
                );
                assert!(!demo.press_busy);
                let draft = demo.flow_draft.clone().expect("the draft came back");
                assert_eq!(draft.journal.game_id(), Some(42), "01 is journaled");
                assert_eq!(
                    draft.journal.next_owed(crate::draft::Ladder::Game),
                    2,
                    "a resumed press starts at the write that failed"
                );
                assert!(matches!(
                    demo.press_outcome,
                    Some((_, crate::commit::Outcome::Stopped { position: 2, .. }))
                ));
            })
        });
    }

    /// Dragging a leaf row onto the map deploys it there — source payload,
    /// ghost, map drop and fractions, proven in-harness end to end. The
    /// source is found by sweep, never by hardcoded pixels: the press walks
    /// down the leaf column until GPUI reports an active drag. The hull is
    /// NOT in the exercise, so the drop assigns first — placing IS
    /// assigning — and the verb carries the operator's own seat.
    #[gpui::test]
    fn dragging_a_leaf_row_to_the_map_deploys_it(cx: &mut gpui::TestAppContext) {
        let (tx, rx) = std::sync::mpsc::channel();
        let (view, cx) = cx.add_window_view(|_, _| {
            let mut session = SessionView::default();
            session.me = 7;
            session.people = vec![PersonView {
                id: 7,
                name: "SU".to_string(),
                call_sign: "SUEX".to_string(),
                role: "Commando".to_string(),
                role_id: 1,
                judge: false,
                ready: false,
                present: true,
            }];
            let mut demo = IslandDemo::new(fixture_roster(), 8, 0, session, tx);
            demo.fleet_tax = super::fleet_taxonomy_tests::fixture_taxonomy();
            demo.select_category(2);
            demo.select_type(3);
            demo.select_class(5);
            demo.fleet_open = true;
            demo
        });
        cx.simulate_resize(gpui::size(gpui::px(768.0), gpui::px(838.0)));
        // The live viewport, never assumed: a resize that lags a frame
        // would put hardcoded points outside the window, and a drop outside
        // the window is a silence, not a failure.
        let (w, h) = cx.update(|window, _| {
            let s = window.viewport_size();
            (f32::from(s.width), f32::from(s.height))
        });
        // The leaf column sits ~486pt inside the centred 700-wide modal.
        let lx = (w - 700.0) / 2.0 + 486.0;
        // Bare map below the centred modal and clear of the left column.
        let (dx, dy) = (w - 68.0, h - 58.0);
        // The sweep-and-drop in one pass: press-and-nudge down the leaf
        // column, and the press that starts a drag KEEPS going — straight
        // to bare map below the modal, where it releases. One pass because
        // a probe release fires the drop too (the map underlies everything
        // hoverable), and that deploy re-renders the picker's status line,
        // shifting every row below the press that found it. Probes that
        // find nothing release harmlessly; clicks that land on add post
        // force plans, skipped at the sink below.
        let mut found = false;
        let mut y = 150.0;
        while y < h - 100.0 && !found {
            cx.simulate_mouse_down(
                gpui::point(gpui::px(lx), gpui::px(y)),
                gpui::MouseButton::Left,
                gpui::Modifiers::default(),
            );
            cx.simulate_mouse_move(
                gpui::point(gpui::px(lx), gpui::px(y + 20.0)),
                gpui::MouseButton::Left,
                gpui::Modifiers::default(),
            );
            if cx.update(|_, app| app.has_active_drag()) {
                found = true;
                for (x, yy) in [
                    (lx + 40.0, y + 60.0),
                    (w - 148.0, 500.0),
                    (w - 108.0, 640.0),
                    (dx, dy),
                ] {
                    cx.simulate_mouse_move(
                        gpui::point(gpui::px(x), gpui::px(yy)),
                        gpui::MouseButton::Left,
                        gpui::Modifiers::default(),
                    );
                }
            }
            cx.simulate_mouse_up(
                gpui::point(
                    gpui::px(if found { dx } else { lx }),
                    gpui::px(if found { dy } else { y + 20.0 }),
                ),
                gpui::MouseButton::Left,
                gpui::Modifiers::default(),
            );
            y += 8.0;
        }
        assert!(found, "some leaf row must start a drag");
        // The drop is last: anything the sweep posted before it (force
        // plans from add clicks) is skipped, the assign-and-deploy is
        // verified.
        let mut deploy = None;
        while let Ok(msg) = rx.try_recv() {
            if matches!(msg, ToBinary::DeployAssign { .. }) {
                deploy = Some(msg);
            }
        }
        match deploy.expect("the drop reached the sink") {
            ToBinary::DeployAssign {
                unit_id,
                commander_id,
                fx,
                fy,
            } => {
                assert_eq!(unit_id, 13, "the first leaf row drags Yani");
                assert_eq!(commander_id, 7, "placing assigns to the operator's seat");
                assert!(
                    ((fx - f64::from(dx / w)) as f32).abs() < 0.03,
                    "fx names the drop, got {fx}"
                );
                assert!(
                    ((fy - f64::from(dy / h)) as f32).abs() < 0.03,
                    "fy names the drop, got {fy}"
                );
            }
            other => panic!("expected an assign-and-deploy, got {other:?}"),
        }
        let _ = view;
    }

    /// Dropping a leaf row on a placed host's marker embarks it aboard —
    /// the same sweep-and-hold path as the deploy proof, with a live marker
    /// under the drop. The marker is the test's own (map space 1:1 with the
    /// window here), the host is a placed piece, and the child rides along.
    ///
    /// THE SPEC COMES FIRST, so the drop is a two-beat gesture: the release
    /// asks the server what the host carries, and the attach is posted when
    /// that answer says the embark is allowed.
    #[gpui::test]
    fn dropping_a_leaf_row_on_a_host_embarks_it(cx: &mut gpui::TestAppContext) {
        let (tx, rx) = std::sync::mpsc::channel();
        let (view, cx) = cx.add_window_view(|_, _| {
            let mut session = SessionView::default();
            // The exercise the embark reads: the spec is read in the HELD
            // game, and a drop with no game has nowhere to read from.
            session.game_id = 8;
            // The CHILD is listed first, and that is load-bearing: the picker
            // draws every piece row ABOVE the taxonomy drill, and the sweep
            // below takes the first row that starts a drag. Listing the host
            // first would hand the sweep the host's own row, and a hull
            // dropped on its own marker is refused — which would prove the
            // refusal, not the embark.
            session.pieces = vec![
                PieceView {
                    id: 13,
                    label: "KRI Yos Sudarso".to_string(),

                    class_name: String::new(),
                    commander_id: None,
                    commander_name: String::new(),
                    hierarchy_node: None,
                    start: None,
                    placed: false,
                },
                PieceView {
                    id: 8,
                    label: "KRI Ahmad Yani".to_string(),

                    class_name: String::new(),
                    commander_id: None,
                    commander_name: String::new(),
                    hierarchy_node: None,
                    start: None,
                    placed: true,
                },
            ];
            let mut demo = IslandDemo::new(fixture_roster(), 8, 0, session, tx);
            demo.fleet_tax = super::fleet_taxonomy_tests::fixture_taxonomy();
            demo.select_category(2);
            demo.select_type(3);
            demo.select_class(5);
            demo.fleet_open = true;
            // The register's read of the child's kind: a class-5 hull, which
            // is what the spec below says the host carries.
            demo.unit_taxonomy.insert(13, class_five_tax());
            // Map space 1:1 with the window, so marker pixels ARE window
            // pixels and the drop below names the marker exactly.
            demo.map_dims = (768.0, 838.0);
            // The camera the marker's ground is projected at: the centre
            // and the zoom the marker's own x/y were written for.
            demo.map_center = (0.0, 0.0);
            demo.map_zoom = 0.0;
            // The marker's ground is the inverse of the pixel the drop
            // names: the shell now projects every marker from its fix at the
            // frame's camera, so a marker placed at x/y alone would not land
            // there.
            let (marker_lat, marker_lon) =
                map_geometry::unproject_mercator(600.0, 750.0, (0.0, 0.0), 0.0, 768.0, 838.0);
            demo.live = vec![LiveMarker {
                id: "8".to_string(),
                x: 600.0,
                y: 750.0,
                stale: false,
                symbol: MapSymbolShape::Frigate,
                affiliation: symbology::Affiliation::Unknown,
                heading_deg: None,
                speed_kn: None,
                latitude: marker_lat,
                longitude: marker_lon,
                trail: 0,
            }];
            demo
        });
        cx.simulate_resize(gpui::size(gpui::px(768.0), gpui::px(838.0)));
        let (w, h) = cx.update(|window, _| {
            let s = window.viewport_size();
            (f32::from(s.width), f32::from(s.height))
        });
        let lx = (w - 700.0) / 2.0 + 486.0;
        // Onto the host's marker: below the centred modal, clear of the
        // left column — bare map with a hull on it.
        let (dx, dy) = (600.0, 750.0);
        let mut found = false;
        let mut y = 150.0;
        while y < h - 100.0 && !found {
            cx.simulate_mouse_down(
                gpui::point(gpui::px(lx), gpui::px(y)),
                gpui::MouseButton::Left,
                gpui::Modifiers::default(),
            );
            cx.simulate_mouse_move(
                gpui::point(gpui::px(lx), gpui::px(y + 20.0)),
                gpui::MouseButton::Left,
                gpui::Modifiers::default(),
            );
            if cx.update(|_, app| app.has_active_drag()) {
                found = true;
                for (x, yy) in [(lx + 40.0, y + 60.0), (620.0, 700.0), (dx, dy)] {
                    cx.simulate_mouse_move(
                        gpui::point(gpui::px(x), gpui::px(yy)),
                        gpui::MouseButton::Left,
                        gpui::Modifiers::default(),
                    );
                }
            }
            cx.simulate_mouse_up(
                gpui::point(
                    gpui::px(if found { dx } else { lx }),
                    gpui::px(if found { dy } else { y + 20.0 }),
                ),
                gpui::MouseButton::Left,
                gpui::Modifiers::default(),
            );
            y += 8.0;
        }
        assert!(found, "some leaf row must start a drag");
        // The first beat: the release asks what the host carries. Nothing is
        // posted yet — the embark is decided against that answer.
        let mut asked = None;
        while let Ok(msg) = rx.try_recv() {
            if let ToBinary::ReadEmbarkSpec { host } = msg {
                asked = Some(host);
            }
        }
        assert_eq!(
            asked.expect("the drop asked for the spec"),
            8,
            "the drop named the host marker"
        );
        // The second beat: the answer says the host carries the child's kind,
        // and the attach is posted.
        cx.update(|_, app| {
            view.update(app, |demo, cx| {
                demo.apply_embark_spec(Ok(host_spec(8, 5, 2)), cx)
            })
        });
        let mut embark = None;
        while let Ok(msg) = rx.try_recv() {
            if matches!(msg, ToBinary::EmbarkDrop { .. }) {
                embark = Some(msg);
            }
        }
        match embark.expect("the drop reached the sink") {
            ToBinary::EmbarkDrop { host, child } => {
                assert_eq!(host, 8, "the drop named the host marker");
                assert_eq!(child, 13, "the first leaf row rides along");
            }
            other => panic!("expected an embark, got {other:?}"),
        }
        let _ = view;
    }

    /// The picker hides while a drag is in flight and returns when it
    /// ends — the flag the tick polls, pinned here without a pointer.
    #[gpui::test]
    fn dragging_hides_the_picker(cx: &mut gpui::TestAppContext) {
        let (view, cx) = cx.add_window_view(|_, _| {
            let mut demo = IslandDemo::new(
                fixture_roster(),
                8,
                0,
                SessionView::default(),
                std::sync::mpsc::channel().0,
            );
            demo.fleet_open = true;
            demo
        });
        cx.update(|_, app| {
            view.update(app, |demo, cx| demo.set_dragging(true, cx));
        });
        let hiding = cx.update(|_, app| view.read(app).dragging);
        assert!(hiding, "a live drag hides the picker");
        cx.update(|_, app| {
            view.update(app, |demo, cx| demo.set_dragging(false, cx));
        });
        let back = cx.update(|_, app| {
            let d = view.read(app);
            !d.dragging && d.fleet_open
        });
        assert!(back, "the drop's end returns the picker, still open");
    }

    /// Pressing the fleet picker's card never pans the map — the press
    /// belongs to the picker, and the map handle underneath must not see
    /// it. GPUI delivers a press to EVERY hovered hitbox down the chain,
    /// and the full-window map surface is always in it — so without the
    /// card truncating hover, every picker drag (and every press-and-move
    /// on the card) drags the map along with the gesture.
    #[gpui::test]
    fn pressing_the_picker_card_does_not_pan_the_map(cx: &mut gpui::TestAppContext) {
        let (tx, rx) = std::sync::mpsc::channel();
        let (_view, cx) = cx.add_window_view(|_, _| {
            let mut demo = IslandDemo::new(fixture_roster(), 8, 0, SessionView::default(), tx);
            demo.fleet_tax = super::fleet_taxonomy_tests::fixture_taxonomy();
            demo.select_category(2);
            demo.select_type(3);
            demo.select_class(5);
            demo.fleet_open = true;
            // A framed map, or panning computes nothing: the pan scales by
            // the frame's dimensions, and a (0, 0) frame refuses every move.
            demo.map_dims = (768.0, 838.0);
            demo
        });
        cx.simulate_resize(gpui::size(gpui::px(768.0), gpui::px(838.0)));
        // The card's right padding: dead card background, no control. A
        // press-drag here must reach nothing but the card.
        let at = gpui::point(gpui::px(720.0), gpui::px(400.0));
        cx.simulate_mouse_down(at, gpui::MouseButton::Left, gpui::Modifiers::default());
        cx.simulate_mouse_move(
            gpui::point(gpui::px(740.0), gpui::px(440.0)),
            gpui::MouseButton::Left,
            gpui::Modifiers::default(),
        );
        cx.simulate_mouse_up(
            gpui::point(gpui::px(740.0), gpui::px(440.0)),
            gpui::MouseButton::Left,
            gpui::Modifiers::default(),
        );
        let mut panned = false;
        while let Ok(msg) = rx.try_recv() {
            // A pan is now a camera move: the message that carries it is the
            // camera's, and it is the map that has to stay put.
            if let ToBinary::Camera { center, .. } = msg {
                if center != (0.0, 0.0) {
                    panned = true;
                }
            }
        }
        assert!(!panned, "a press on the picker card must not pan the map");
    }

    /// A remote command moves the camera through the SAME path a gesture uses,
    /// and the camera it sends names the client and command that asked. This
    /// is the shell's half of the control plane: the order thread attributes
    /// the resulting `camera.changed` from the tag it finds here.
    #[gpui::test]
    fn a_remote_nudge_moves_the_camera_west_and_names_its_command(cx: &mut gpui::TestAppContext) {
        let (tx, rx) = std::sync::mpsc::channel();
        let (view, cx) = cx.add_window_view(|_, _| {
            IslandDemo::new(fixture_roster(), 8, 0, SessionView::default(), tx)
        });
        // The frame's size, which a fraction-of-viewport nudge resolves
        // against. A real launch learns it from the first picture.
        cx.update(|_, app| {
            view.update(app, |demo, _| {
                demo.map_dims = (800.0, 600.0);
                demo.map_px = (800, 600);
            })
        });
        let before = cx.update(|_, app| view.read(app).map_center);
        let source = crate::control::CameraSource {
            client_id: "tfgctl".to_string(),
            command_id: Some("c-1".to_string()),
        };
        cx.update(|_, app| {
            view.update(app, |demo, cx| {
                demo.apply_control_command(
                    crate::control::Command::CameraNudge {
                        dx_fraction: 0.25,
                        dy_fraction: 0.0,
                    },
                    source.clone(),
                    cx,
                )
            })
        });
        let mut moved = None;
        while let Ok(msg) = rx.try_recv() {
            if let ToBinary::Camera {
                center,
                zoom,
                control,
                ..
            } = msg
            {
                moved = Some((center, zoom, control));
            }
        }
        let (center, zoom, control) = moved.expect("the command reached the sink");
        assert!(
            center.1 < before.1,
            "a positive dx_fraction moves the camera west: {before:?} -> {center:?}"
        );
        assert!(
            (center.0 - before.0).abs() < 1e-9,
            "a horizontal nudge must not move the latitude: {before:?} -> {center:?}"
        );
        assert_eq!(zoom, cx.update(|_, app| view.read(app).map_zoom));
        assert_eq!(
            control,
            Some(source),
            "the camera message must name the command that moved it"
        );
    }

    /// A nudge that arrives before the map's first picture is applied, not
    /// dropped: the frame the shell will ask for is already a size.
    #[gpui::test]
    fn a_remote_nudge_works_before_the_first_frame(cx: &mut gpui::TestAppContext) {
        let (tx, rx) = std::sync::mpsc::channel();
        let (view, cx) = cx.add_window_view(|_, _| {
            IslandDemo::new(fixture_roster(), 8, 0, SessionView::default(), tx)
        });
        let before = cx.update(|_, app| view.read(app).map_center);
        assert_eq!(
            cx.update(|_, app| view.read(app).map_dims),
            (0.0, 0.0),
            "this test is about the state before a picture arrives"
        );
        cx.update(|_, app| {
            view.update(app, |demo, cx| {
                demo.apply_control_command(
                    crate::control::Command::CameraNudge {
                        dx_fraction: 0.25,
                        dy_fraction: 0.0,
                    },
                    crate::control::CameraSource::desktop(),
                    cx,
                )
            })
        });
        let mut moved = None;
        while let Ok(msg) = rx.try_recv() {
            if let ToBinary::Camera { center, .. } = msg {
                moved = Some(center);
            }
        }
        let center = moved.expect("the nudge reached the sink");
        assert!(
            center.1 < before.1,
            "the camera still moves west with no frame yet: {before:?} -> {center:?}"
        );
    }

